mapper.select:
select t.month_key as name, t.amount as value
from (
  select DATE_FORMAT(tt.deal_time, '%Y-%m') as month_key,
         ifnull(sum(tt.money), 0) as amount
  from t_tran tt
  where tt.deal_time is not null and tt.deal_time >= #{startTime}
  group by DATE_FORMAT(tt.deal_time, '%Y-%m')
) t
order by name

select count(1) from t_tran tt
where exists (
  select 1 from t_tran t2
  where t2.customer_id = tt.customer_id and t2.deal_time < tt.deal_time
)
and tt.deal_time >= #{startTime}
and tt.deal_time <= #{endTime}
and tt.create_by = #{userId}

select * from t_customer


    and source in
    #{s}


    and course_type in
    #{c}


    and studying in
    #{st}


    and create_by in
    #{cb}


    and (

      (age >= cast(substring_index(#{ar}, '-', 1) as signed)
       and age < cast(substring_index(#{ar}, '-', -1) as signed))

    )

select * from t_clue


    and source in #{s}


    and intention_course in #{c}


    and clue_status in #{st}


    and intention_strength in #{is}


    and create_by in #{cb}


    and (

      (age >= cast(substring_index(#{ar}, '-', 1) as signed)
       and age < cast(substring_index(#{ar}, '-', -1) as signed))

    )
